(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"original":{"h":"WHAT YOU ARE LOOKING AT","t":"Take every unit-length vector: together they form a **circle**. The two arrows mark special **perpendicular directions**."},"rotate-input":{"h":"STEP 1: ROTATE THE INPUT (Vᵀ)","t":"First, rotate so those special directions **line up with the axes**. Rotating a circle changes nothing about its shape."},"scale":{"h":"STEP 2: STRETCH ALONG THE AXES (Σ)","t":"Next, stretch along the axes by different amounts: **×3 horizontally and ×1 vertically**. The circle becomes an **ellipse**."},"rotate-output":{"h":"STEP 3: ROTATE THE OUTPUT (U)","t":"Finally, rotate the ellipse into its final position. **Rotate, stretch, rotate:** that is every matrix, **A = U Σ Vᵀ**."},"singular-values":{"h":"THE STRETCH AMOUNTS ARE THE SINGULAR VALUES","t":"The ellipse's two radii are the **singular values**: **σ₁ = 3** for the long direction and **σ₂ = 1** for the short one."},"rank-approximation":{"h":"KEEP ONLY THE BIGGEST SINGULAR VALUE","t":"Drop σ₂ and the ellipse flattens to a line. This **rank-1 approximation** keeps **9 of every 10** units of “energy”: 3² / (3² + 1²) = **90%**."},"ml-connection":{"h":"TAKEAWAY","t":"Keeping the **large singular values** gives a smaller, cleaner version of the data. That powers **compression, denoising and dimensionality reduction**."}};
  // ── scene ──
  var steps = [
    { id: "original", label: "Start with a circle of vectors", caption: "Take every unit-length vector: together they form a circle. The two arrows mark special perpendicular directions." },
    { id: "rotate-input", label: "Step 1: rotate the input (Vᵀ)", caption: "First, rotate so those special directions line up with the axes. Rotating a circle changes nothing about its shape." },
    { id: "scale", label: "Step 2: stretch along the axes (Σ)", caption: "Next, stretch along the axes by different amounts: ×3 horizontally and ×1 vertically. The circle becomes an ellipse." },
    { id: "rotate-output", label: "Step 3: rotate the output (U)", caption: "Finally, rotate the ellipse into its final position. Rotate, stretch, rotate: that is every matrix, A = U Σ Vᵀ." },
    { id: "singular-values", label: "The stretch amounts are the singular values", caption: "The ellipse's two radii are the singular values: σ₁ = 3 for the long direction and σ₂ = 1 for the short one." },
    { id: "rank-approximation", label: "Keep only the biggest singular value", caption: "Drop σ₂ and the ellipse flattens to a line. This rank-1 approximation keeps 9 of every 10 units of 'energy': 3² / (3² + 1²) = 90%." },
    { id: "ml-connection", label: "Why this matters for ML", caption: "Keeping the large singular values gives a smaller, cleaner version of the data. That powers compression, denoising and dimensionality reduction." }
  ];

  var P = makePlane(220, 190, 46);
  var N = 48;
  var circle = [];
  for (var i = 0; i < N; i++) circle.push([Math.cos((2 * Math.PI * i) / N), Math.sin((2 * Math.PI * i) / N)]);
  var D = Math.SQRT1_2;
  var M1 = [D, D];
  var M2 = [-D, D];

  var st = { a: 0, sx: 1, sy: 1, c: 0 };
  function rot(p, deg) {
    var r = (deg * Math.PI) / 180;
    return [p[0] * Math.cos(r) - p[1] * Math.sin(r), p[0] * Math.sin(r) + p[1] * Math.cos(r)];
  }
  function xf(p) {
    var q = rot(p, -45 * st.a);
    q = [q[0] * st.sx, q[1] * st.sy];
    return rot(q, 45 * st.c);
  }

  axes(svg, P, 4.2, 3.9);
  var shape = polygon(svg, "fillA");
  var arr1 = arrow(svg, "y", 4);
  var arr2 = arrow(svg, "p", 4);
  var lab1 = txt(svg, 0, 0, "lbl lbl-y", "", "start");
  var lab2 = txt(svg, 0, 0, "lbl lbl-p", "", "start");
  var stage = txt(svg, 30, 40, "big", "", "start");

  function draw() {
    setPoly(shape, circle.map(function (p) { return P.pt(xf(p)); }));
    var t1 = P.pt(xf(M1)), t2 = P.pt(xf(M2));
    setLine(arr1, P.x(0), P.y(0), t1[0], t1[1]);
    setLine(arr2, P.x(0), P.y(0), t2[0], t2[1]);
    lab1.setAttribute("x", t1[0] + 8); lab1.setAttribute("y", t1[1] - 6);
    lab2.setAttribute("x", t2[0] - 8); lab2.setAttribute("y", t2[1] - 8);
    lab2.setAttribute("text-anchor", "end");
  }
  draw();

  // Singular value bars.
  var bars = el("g", { opacity: 0 }, svg);
  el("rect", { x: 436, y: 70, width: 190, height: 110, rx: 12, class: "fillG" }, bars);
  txt(bars, 450, 94, "lbl", "singular values", "start");
  el("rect", { x: 450, y: 106, width: 3 * 40, height: 16, rx: 4, fill: "#e2b44a" }, bars);
  txt(bars, 450 + 3 * 40 + 6, 119, "lbl lbl-y", "", "start");
  el("rect", { x: 450, y: 134, width: 1 * 40, height: 16, rx: 4, fill: "#f472b6" }, bars);
  var bar2 = bars.lastChild;
  txt(bars, 450 + 40 + 6, 147, "lbl lbl-p", "", "start");
  var barTxt = bars.querySelectorAll("text");

  var chips = el("g", { opacity: 0 }, svg);
  ["compression", "denoising", "dimensionality reduction"].forEach(function (c, i) {
    el("rect", { x: 420, y: 100 + i * 44, width: 204, height: 34, rx: 10, class: "fillG" }, chips);
    txt(chips, 434, 122 + i * 44, "lbl", c, "start");
  });

  function goState(target, ms) {
    var from = { a: st.a, sx: st.sx, sy: st.sy, c: st.c };
    anim("svd", ms, function (e) {
      st.a = lerp(from.a, target.a, e);
      st.sx = lerp(from.sx, target.sx, e);
      st.sy = lerp(from.sy, target.sy, e);
      st.c = lerp(from.c, target.c, e);
      draw();
    });
  }

  function render(index, id) {
    lab1.textContent = ""; lab2.textContent = "";
    show(bars, id === "singular-values" || id === "rank-approximation");
    show(chips, id === "ml-connection");
    show(arr2, true);
    stage.textContent = "";
    barTxt[1].textContent = "σ₁ = 3";
    barTxt[2].textContent = id === "rank-approximation" ? "σ₂ → 0 (dropped)" : "σ₂ = 1";
    bar2.setAttribute("width", id === "rank-approximation" ? 2 : 40);

    if (id === "original") goState({ a: 0, sx: 1, sy: 1, c: 0 }, 300);
    else if (id === "rotate-input") { goState({ a: 1, sx: 1, sy: 1, c: 0 }, 1000); stage.textContent = "Vᵀ  rotate"; }
    else if (id === "scale") { goState({ a: 1, sx: 3, sy: 1, c: 0 }, 1000); stage.textContent = "Σ  stretch"; }
    else if (id === "rotate-output") { goState({ a: 1, sx: 3, sy: 1, c: 1 }, 1000); stage.textContent = "U  rotate"; }
    else if (id === "singular-values") {
      goState({ a: 1, sx: 3, sy: 1, c: 1 }, 200);
      lab1.textContent = "σ₁ = 3"; lab2.textContent = "σ₂ = 1";
    } else if (id === "rank-approximation") {
      goState({ a: 1, sx: 3, sy: 0.02, c: 1 }, 1000);
      lab1.textContent = "keep σ₁";
      show(arr2, false);
    } else {
      goState({ a: 1, sx: 3, sy: 0.02, c: 1 }, 200);
      show(arr2, false);
    }
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();

